questionvariables.text:
/* Define the known points */
x1: 1;
x2: 3;
sq_aa:(rand(4)+2)^2;
y1: rand(5)+2;
y2: y1*sq_aa;
eq1: y1 = C*a^x1;
eq2: y2 = C*a^x2;
fx11:rhs(solve(eq1,a)[1]);
sol_c:solve(at(eq2,[a=fx11]));
cor_c1:rhs(sol_c[2]);
cor_c2:rhs(sol_c[1]);
cor_a1:rhs(solve(at(eq1,[C=cor_c1]))[1]);
cor_a2:rhs(solve(at(eq1,[C=cor_c2]))[1]);
/* Define the exponential function */
cor_fx : cor_c1 * cor_a1^x;
alt_fx: cor_c2 * cor_a1^x;

ta1:cor_fx;
ta2:alt_fx;

feedbackvariables.text:
setta:{ta1,ta2};
setans:{ans1,ans2};
incansset:setdifference(setans,setta);
numans:cardinality(incansset);
incans:if numans=1 then listify(incansset)[1] else "";
